class Solution:
    def minXORPath(self, grid):
        m, n = len(grid), len(grid[0])
        best = [1 << 30]
        def dfs(i, j, x):
            x ^= grid[i][j]
            if i == m - 1 and j == n - 1:
                best[0] = min(best[0], x)
                return
            if i + 1 < m: dfs(i + 1, j, x)
            if j + 1 < n: dfs(i, j + 1, x)
        dfs(0, 0, 0)
        return best[0]

