    private int[][] g;
    public int minXORPath(int[][] grid) {
        g = grid; m = grid.length; n = grid[0].length;
        dfs(0, 0, 0);
        return best;
    }
    private void dfs(int i, int j, int x) {
        x ^= g[i][j];
        if (i == m - 1 && j == n - 1) { best = Math.min(best, x); return; }
        if (i + 1 < m) dfs(i + 1, j, x);
        if (j + 1 < n) dfs(i, j + 1, x);
    }
}

