class Solution:
    def minXORPath(self, grid):
        m, n = len(grid), len(grid[0])
        F = 1 << 10
        prev = None
        for i in range(m):
            cur = []
            for j in range(n):
                row = [False] * F
                x = grid[i][j]
                if i == 0 and j == 0:
                    row[x] = True
                else:
                    if i > 0:
                        for v in range(F):
                            if prev[j][v]: row[v ^ x] = True
                    if j > 0:
                        for v in range(F):
                            if cur[j - 1][v]: row[v ^ x] = True
                cur.append(row)
            prev = cur
        last = prev[n - 1]
        return min(v for v in range(F) if last[v])

