class Solution {
public:
    int minXORPath(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size(), F = 1 << 10;
        vector<vector<char>> prev;
        for (int i = 0; i < m; i++) {
            vector<vector<char>> cur(n, vector<char>(F, 0));
            for (int j = 0; j < n; j++) {
                int x = grid[i][j];
                if (i == 0 && j == 0) cur[j][x] = 1;
                else {
                    if (i > 0) for (int v = 0; v < F; v++) if (prev[j][v]) cur[j][v ^ x] = 1;
                    if (j > 0) for (int v = 0; v < F; v++) if (cur[j - 1][v]) cur[j][v ^ x] = 1;
                }
            }
            prev = move(cur);
        }
        int ans = F;
        for (int v = 0; v < F; v++) if (prev[n - 1][v]) ans = min(ans, v);
        return ans;
    }
};

