                if (i == 0 && j == 0) cur[j][x] = true;
                else {
                    if (i > 0) for (int v = 0; v < F; v++) if (prev[j][v]) cur[j][v ^ x] = true;
                    if (j > 0) for (int v = 0; v < F; v++) if (cur[j - 1][v]) cur[j][v ^ x] = true;
