var minXORPath = function(grid) {
    const m = grid.length, n = grid[0].length, F = 1 << 10;
    let prev = null;
    for (let i = 0; i < m; i++) {
        const cur = [];
        for (let j = 0; j < n; j++) {
            const row = new Array(F).fill(false);
            const x = grid[i][j];
            if (i === 0 && j === 0) row[x] = true;
            else {
                if (i > 0) for (let v = 0; v < F; v++) if (prev[j][v]) row[v ^ x] = true;
                if (j > 0) for (let v = 0; v < F; v++) if (cur[j - 1][v]) row[v ^ x] = true;
            }
            cur.push(row);
        }
        prev = cur;
    }
    const last = prev[n - 1];
    for (let v = 0; v < F; v++) if (last[v]) return v;
    return 0;
};
